                cells = Some(rest.iter().map(|s| (*s).to_string()).collect())
            }
            ["mode", "heat"] if mode.is_none() => mode = Some(true),
            ["mode", "peek"] if mode.is_none() => mode = Some(false),
            ["swap", a, b] if old.is_none() => {
                old = Some((*a).to_string()); new = Some((*b).to_string());
            }
            ["push", v] if extra.is_none() => extra = Some((*v).to_string()),
            _ => return None,
        }
    }
    let heat = mode?;
    if heat && (old.is_none() || new.is_none() || extra.is_none()) { return None; }
    if !heat && (old.is_some() || new.is_some() || extra.is_some()) { return None; }
    let cells = cells?;
    let ids = (0..cells.len()).collect();
    Some((
        hold::Sess { n0: n0?, n1: n1?, ids: Rc::new(RefCell::new(ids)), flag: heat },
        hold::Pool { cells },
        Plan { old: old.unwrap_or_default(), new: new.unwrap_or_default(), extra: extra.unwrap_or_default() },
    ))
}

pub fn step(a: &mut hold::Sess, b: &mut hold::Pool, p: &Plan) {
    let width = a.ids.borrow().len() as u32;
    if a.flag {
        for c in &mut b.cells {
            if *c == p.old { *c = p.new.clone(); }
        }
        b.cells.push(p.extra.clone());
        a.ids.borrow_mut().push(b.cells.len() - 1);
    }
    (a.n0, a.n1) = kiln_pitch(a.n0, a.n1, width, a.flag);
}
